export const DataFreshness = z.object({ "coverage_end": z.union([z.string(), z.null()]).describe("The last data point in the card's data, at the granularity of the underlying series. An annual series reports a year (2026). A monthly or quarterly series reports a month (2026-06). A daily or intraday series reports a full date (2026-06-30). This value can be in the future when the card includes projections. Null for card types without a coverage date. The value uses ISO 8601 reduced precision, so examine the length before you parse it. A date parser reads 2026 as 2026-01-01, which is the start of the period and not the end.").optional(), "data_as_of": z.union([z.string(), z.null()]).describe("Deprecated: use coverage_end. The same point, always as a full ISO date (YYYY-MM-DD). For a series whose points are periods, this date is the period boundary. It is not a day on which Tako observed a value.").optional(), "last_updated": z.union([z.string(), z.null()]).describe("Date Tako last refreshed the underlying data, as an ISO date (YYYY-MM-DD).").optional() }).describe("When the card's data ends and when Tako last refreshed it. Either field\nmay be null when that date is not available for the card type.");
export type DataFreshness = z.infer<typeof DataFreshness>;

export const DataPipelineAnswerEvent = z.object({ "kind": z.literal("data_pipeline_answer").default("data_pipeline_answer"), "id": z.string(), "chart_refs": z.array(z.string()).optional() }).describe("Signals that the data pipeline produced one or more charts for the\nanswer. It carries only chart references. The answer text streams in\n`text` events, and the structured result arrives in the terminal\n`agent_result` event, not here.");
export type DataPipelineAnswerEvent = z.infer<typeof DataPipelineAnswerEvent>;

export const DataSourceSettings = z.object({ "count": z.number().int().gte(1).lte(20).describe("Maximum number of results to return for this source. 1-20.").default(5), "include_contents": z.boolean().describe("Inline this source's underlying data directly in the response. For the Tako data source, that is serialized card data (see content_format). For web results, that is the extracted text.").default(false), "mode": z.lazy(() => ContentsDeliveryMode).describe("Delivery for inlined card data when include_contents is true. For Tako cards, include_contents always returns the most-recent rows in the response body, up to max_rows, or up to the default inline row cap for your account if you omit max_rows. This field therefore has no effect on Tako cards; it stays for schema stability. total_rows and truncated on the returned content indicate when more data is available. For a presigned download link, call POST /api/v1/contents with mode='url'.").default("inline"), "content_format": z.lazy(() => ContentsFormat).describe("Serialization for card data: 'json_compact' (default), 'json_records', 'csv', or 'card_json'. The first three return a free row-capped preview. 'card_json' returns a rich card-type-specific JSON object under card_data, truncated to the same row cap, and Tako bills the record rows it returns. A card type with no card_json shape falls back to 'json_compact' for that card.").default("json_compact"), "max_rows": z.union([z.number().int().gte(1), z.null()]).describe("Maximum number of card data rows to inline when include_contents is true. If you omit this field, Tako returns the default inline row cap for your account (20 rows on the standard plan), which is not always the same as your free row allowance. Raise it to inline more rows, up to the 2,000-row system ceiling. Tako clamps a larger value to that ceiling. Once rows exceed the free row allowance, Tako charges a flat per-card baseline fee plus the per-1,000-row rate, the same rate POST /api/v1/contents charges. total_rows and truncated report whether more rows remain. A single response also has a 2,000 billable-row budget and a 20,000-row total budget, both shared across all cards. A later card can therefore return fewer rows than you requested, or no inlined rows at all. Such a card still carries its export_pricing quote, so you can fetch its rows with POST /api/v1/contents.").optional(), "node_ids": z.array(z.string()).max(20).describe("Graph node ids to pin into the search; the /v1/graph endpoints return these ids. Pinned nodes always become retrieval candidates and get a strong boost; organic results do not change. Ids are not durable across knowledge-graph rebuilds: the search skips an id that no longer resolves (in strict mode it simply cannot match). Malformed ids fail the request with a 400. Max 20.").optional(), "strict": z.boolean().describe("When true, return only data cards that match at least one node in node_ids (which must then be non-empty). When false (the default), pinned nodes rank first but organic results still return. Web results do not change either way.").default(false) }).strict().describe("Tako data (card) source settings. It adds the two contents-export\nfields on top of the base count and include_contents. Web sources use the\nbase SourceSettings: Tako always inlines web content as raw text, so web\ncarries neither field.");
export type DataSourceSettings = z.infer<typeof DataSourceSettings>;

