export const ExportPricing = z.object({ "baseline_usd": z.number().describe("Flat USD charged once per card export, independent of row count."), "row_cpm_usd": z.number().describe("USD charged per 1,000 rows on rows beyond the free allowance (free_rows). Card-level rate, set by the card's most expensive source; no per-source breakdown."), "free_rows": z.number().int().describe("Rows included at the baseline price before the per-1,000-row rate (row_cpm_usd) begins to apply. This is the /contents free row allowance for your account. A search or answer response bills an inlined card against this same allowance."), "max_rows_ceiling": z.number().int().describe("Hard cap on rows a single export can return and bill; a larger requested max_rows is clamped to this. No format bills more than the clamped max_rows, and none bills more rows than it returns. Every format obeys this ceiling, including card_json.") }).describe("Card-CSV export pricing RATE for the /contents endpoint, published so a\ncaller can compute an export's cost before fetching. A /contents export\ncharge = baseline_usd + row_cpm_usd * max(0, rows - free_rows) / 1000,\nrows <= max_rows_ceiling. row_cpm_usd is the card-level rate: the\nper-1,000-row rate of the card's most expensive source (TAKO-3916 — a card\ncosts its most expensive source, never a sum); no per-source breakdown.\n\n`free_rows` here is the CALLER'S allowance, the same number a billed inline\ncard's `cost` uses -- both resolve through tako_free_rows_for. The two agreed\nonly after /contents gained an entitlement concept; before that this field was\nalways CSV_FREE_ROWS and the two surfaces disagreed by 3x on the same rows.");
export type ExportPricing = z.infer<typeof ExportPricing>;

export const GeoLocation = z.object({ "latitude": z.number().gte(-90).lte(90).describe("Latitude of the end user (degrees, -90 to 90)."), "longitude": z.number().gte(-180).lte(180).describe("Longitude of the end user (degrees, -180 to 180).") }).strict();
export type GeoLocation = z.infer<typeof GeoLocation>;

export const GraphNode = z.object({ "id": z.string().describe("Opaque, human-friendly public id (<prefix>::<name>::<hash>, where prefix is ent for an entity or mt for a metric). Ids are not durable across knowledge-graph rebuilds — resolve them at request time rather than storing them."), "type": z.lazy(() => GraphNodeType), "name": z.string(), "aliases": z.array(z.string()).optional(), "description": z.union([z.string(), z.null()]).optional(), "subtype": z.union([z.lazy(() => EntityClassName), z.null()]).optional(), "label": z.union([z.lazy(() => NerLabel), z.null()]).describe("Public NER label of the node (PERSON, ORG, GPE, ...). Derived from the node's stored annotation; null when the internal annotation has no public equivalent.").optional() });
export type GraphNode = z.infer<typeof GraphNode>;

export const GraphNodeType = z.enum(["metric","entity"]);
export type GraphNodeType = z.infer<typeof GraphNodeType>;

export const GraphRelatedResponse = z.object({ "node": z.lazy(() => GraphNode), "relations": z.union([z.array(z.lazy(() => GraphRelation)), z.null()]).optional(), "relation": z.union([z.lazy(() => GraphRelationPage), z.null()]).optional(), "inferred_labels": z.union([z.array(z.lazy(() => NerLabel)), z.null()]).describe("Labels that Tako NER inferred from `q` when infer_label ran (boost applied). An empty list means inference ran and found nothing. The field is absent when you supplied an explicit `label`, when infer_label=false, or when there was no q.").optional() });
