export const GraphRelationPage = z.object({ "key": z.string().describe("The relation key of this page."), "kind": z.lazy(() => RelationKind), "label": z.string().describe("Human-readable group label."), "items": z.array(z.lazy(() => GraphNode)), "total": z.number().int(), "total_capped": z.boolean().describe("True when `total` hit the server-side fetch cap; the true count is at least `total`. Pagination ends at the cap — narrow with `q` to reach the tail.").default(false), "next_cursor": z.union([z.string(), z.null()]).optional() });
