export const OutputSettings = z.object({ "image_dark_mode": z.union([z.boolean(), z.null()]).describe("Whether to render card preview images in dark mode.").optional(), "force_refresh": z.boolean().describe("Instant mode only, and currently informational: on these endpoints, instant (effort='instant') always operates in build-and-refresh mode regardless of this flag. Instant retrieves data for embeds that are missing or stale, then creates or refreshes their static embeds. Embeds that are already fresh (within the refresh cadence) return as-is; Tako does not re-retrieve them. Identical queries therefore reuse the same content-addressed embed and return a stable embed URL.").default(false) }).strict();
