export const RelatedSuggestion = z.object({ "query": z.string().describe("The follow-up query. Send it as the `query` of another search request."), "description": z.union([z.string(), z.null()]).describe("What the query asks for, in words. Tako sets this only when the query text does not say on its own, such as a lookup by identifier. Most suggestions omit it because the query already reads as a question. Tako composes it from the data on the card; no language model writes it.").optional(), "node_ids": z.array(z.string()).describe("Graph node ids that identify the data this query asks for. Pass them as `sources.data.node_ids` on the follow-up search to make the search return that data. The list is empty when Tako cannot resolve the ids; the query still works on its own.").optional() }).describe("One follow-up query for the caller to run next.\n\nA suggestion is deterministic. Tako derives it either from the data a\nreturned card already holds, or from the knowledge graph around that card.\nNo language model writes these.");
export type RelatedSuggestion = z.infer<typeof RelatedSuggestion>;

export const RelationKind = z.enum(["related","data","sibling","membership"]).describe("How Tako derived a relation group.");
export type RelationKind = z.infer<typeof RelationKind>;

export const ResultContent = z.object({ "content_format": z.union([z.lazy(() => ContentsFormat), z.null()]).describe("Serialization of the returned card data: 'csv', 'json_records', 'json_compact', or 'card_json'. Null for web text (always returned as raw text) and for a quote-only response (nothing was serialized).").optional(), "cost": z.number().describe("Price of this item in USD. On a /contents response this is the amount actually billed. On a quote_only response it is a prospective /contents export price, because Tako fetched nothing and billed nothing. On a search or answer downloadable card it is also a prospective price, unless Tako returned more rows than the free row allowance; then it is the amount this response billed for the card. Use export_pricing on its own to price a /contents export of the same card. Do not add this value to that result: they are two prices for the same rows, not two charges.").default(0), "data": z.union([z.string(), z.null()]).describe("Inline payload as text: card data serialized to CSV, or a web page's extracted text. Set only for the 'csv' card format and for web text; null otherwise.").optional(), "records": z.union([z.array(z.record(z.string(), z.union([z.string(), z.number(), z.number().int(), z.boolean(), z.null()]))), z.null()]).describe("Inline card data as verbose JSON: a list of row objects keyed by column name. Set only when content_format is 'json_records'.").optional(), "dataset": z.union([z.lazy(() => TakoDataset), z.null()]).describe("Inline card data as a compact TakoDataset (typed column headers plus positional row arrays). Set only when content_format is 'json_compact'.").optional(), "card_data": z.union([z.record(z.string(), z.any()), z.null()]).describe("Inline card data as a card-type-specific JSON object. The 'card_type' field inside the object names its shape. Set only when content_format is 'card_json'. Tako truncates the record rows in the object to 'max_rows', the same cap every other format takes, and bills the rows it returns. A card whose record array is unbounded caps that array at the platform export ceiling and reports 'truncated': true. The payload then also carries the true count for its record array. Card types without a card_json shape return 422 on /contents and fall back to 'json_compact' on search and answer include_contents.").optional(), "card_data_schema": z.union([z.record(z.string(), z.any()), z.null()]).describe("JSON Schema for the object in 'card_data'. Read it to learn the shape of the payload without parsing the payload. Tako sets this whenever content_format is 'card_json'. It is also set in 'url' delivery mode and on a Contents quote, where 'card_data' is null and the shape is all Tako returns. A search or answer card that you did not ask to inline carries a price but no schema. The 'title' field and the 'card_type' default inside the schema name the shape. The schema describes the payload type, so 'card_data' can omit a field the schema declares: Tako drops a measure the provider did not supply. Null for every other content_format and for web text.").optional(), "url": z.union([z.string(), z.null()]).describe("Presigned download URL for the content, returned in 'url' delivery mode. Null for inline delivery and for quotes; pair with expires_at.").optional(), "expires_at": z.union([z.string(), z.null()]).describe("ISO-8601 timestamp after which the presigned url stops working. Null whenever url is null.").optional(), "total_rows": z.union([z.number().int(), z.null()]).describe("True total number of rows in the card's data, independent of how many rows were returned. Compare with truncated to tell whether more rows are available via a larger max_rows. Null for web text.").optional(), "truncated": z.boolean().describe("True when Tako capped the returned rows and total_rows is larger than the number returned. Tako caps a card at the request max_rows or at the 2,000-row system ceiling. On a search or answer response, Tako also applies a budget of 2,000 billable rows that all cards in the response share, so it can return fewer rows for a later card than max_rows asked for. Rows within the free row allowance do not use that budget, so a request that omits max_rows is never capped by it.").default(false), "export_pricing": z.union([z.lazy(() => ExportPricing), z.null()]).describe("Rate card for a downloadable card CSV, so a caller can compute a full export's cost before fetching. Null for web text and other non-downloadable content.").optional(), "manifest": z.union([z.array(z.lazy(() => ColumnDescriptor)), z.null()]).describe("Per-column metadata, one entry per exported column, in column order: entry i describes column i (CSV header i, json_records key i, or dataset.columns[i]). Each entry carries name (the column header), dtype, unit, metric, and entity. Null for web or quote responses that carry no tabular columns.").optional() }).describe("Describes the downloadable content behind a result.\n\nPricing: for a Tako card CSV export, the charge is a flat per-export\nbaseline plus a per-row CPM, at the rate of the card's most expensive\nsource, on the rows returned beyond the free row allowance. Web text bills\nat the standard Contents rate.\n\nThe meaning of `cost` depends on the surface. On `/contents` responses,\n`cost` is the actual charge, and it reconciles with what that response\nbilled. The exception is a `quote_only` response, where `cost` is a\nprospective price: Tako neither fetched nor billed the export, and the\npayload and url fields are null. On a search or answer downloadable\ncard, `cost` is a prospective `/contents` quote (the per-export baseline\nfloor) unless Tako returned more rows than the caller's free row\nallowance, in which case it is what this response billed for the card. The\nbilled cards sum to `usage.data.cost_usd`, never to\n`usage.total_cost_usd` (which always adds the flat per-request compute\nrate), and only when no web contents were inlined, because every web fetch\ncharge lands in that same `data` field.\n\n`export_pricing` carries the `/contents` export rate, so a caller can\ncompute the full charge of a later export before fetching: baseline_usd +\nrow_cpm_usd * max(0, billed_rows - free_rows) / 1000, where `billed_rows` is\nthe SMALLER of the rows the export returns and `max_rows` clamped to\n`max_rows_ceiling`. One formula covers every format, card_json included:\nevery export returns no more rows than that cap, so a card with fewer rows\nthan the cap bills only the rows it returns. That rate uses the CALLER'S free\nrow allowance, the same one a billed inline card's `cost` uses -- /contents\nresolves the caller's entitlement too. `export_pricing` is null for web text\nand non-downloadable content.\n\nDo NOT combine `cost` with `export_pricing` on a billed inline card. There,\n`cost` is the amount THIS response charged, computed against the caller's\nown inline free row allowance, so it is not a `/contents` price. For a\ncaller whose inline allowance is larger than the `/contents` allowance the\ntwo fields disagree, because the inline charge starts above the larger\nallowance and the published `/contents` formula starts above the smaller\none. Read `cost` for what this response billed. Use `export_pricing` alone\nto price a `/contents` export of the same card.\n\nTako populates exactly one payload group once it delivers contents:\n`data` (CSV or web text), `records` (verbose JSON), `dataset` (compact\nTakoDataset), `card_data` (rich card-type-specific JSON), or `url` plus\n`expires_at` (presigned download).\n`content_format` names the serialization; it is null for web text and\nfor an undelivered quote. Read `content_format` to tell a quote from a\ndelivery: when it is null, this is just the quote (`cost`); fetch the\ncontent later via the Contents endpoint.\n\nDo NOT use \"every payload field is null\" as that test. `card_data_schema`\nis set on a card_json quote and on a card_json `url` delivery, where\n`card_data` is null, so a caller reading absent payloads as \"quote\" reads\nthose two as quotes.");
export type ResultContent = z.infer<typeof ResultContent>;

export const RetrievalAgentEffort = z.literal("medium").describe("Effort taxonomy for the Retrieval Agent (POST /v1/agent/retrieval/runs).\n\nOnly 'medium' is available today. `effort` stays a request field for\nforward compatibility and for parity with AnswerAgentEffort. The values\n'low' and 'high' return 400 at validation.");
export type RetrievalAgentEffort = z.infer<typeof RetrievalAgentEffort>;

export const RetrievalAgentResult = z.object({ "answer": z.union([z.string(), z.null()]).optional(), "cards": z.array(z.lazy(() => TakoCard)).optional(), "citations": z.array(z.lazy(() => AgentAnswerCitation)).optional(), "metadata": z.union([z.lazy(() => AgentAnswerMetadata), z.null()]).optional(), "structured_output": z.union([z.record(z.string(), z.any()), z.null()]).describe("Caller-shaped structured output (present only if the request carried output_schema and status is not 'failed'). Dataset slots contain a TakoDataset envelope of exact retrieved rows, or null when the agent left them unfilled.").optional(), "structured_output_status": z.union([z.lazy(() => StructuredOutputStatus), z.null()]).describe("complete | partial | failed. Present when the request supplied output_schema and the run reached the finalize step. It can be absent when the whole run failed or timed out before finalize; the run-level status and error convey that, and the echoed request.output_schema still identifies the run as structured.").optional(), "structured_output_citations": z.union([z.record(z.string(), z.array(z.number().int())), z.null()]).describe("Best-effort field-path -> citation-index map joining the top-level citations registry (same [n] index space as the answer). Absent when status is 'failed'.").optional(), "unfilled_fields": z.union([z.array(z.string()), z.null()]).describe("Dot-separated paths of unfilled dataset slots; present only if status is 'partial'.").optional(), "structured_output_error": z.union([z.lazy(() => ErrorObject), z.null()]).describe("Why structured output failed; present only if status is 'failed'.").optional(), "refusal_code": z.union([z.string(), z.null()]).describe("Set when Tako rejected the query before the agent ran. Null on normal runs. Tako can add new codes, so accept a code you do not recognize. The current code is 'rejected_input_classifier'.").optional(), "request_id": z.union([z.string(), z.null()]).optional() }).describe("Final retrieval-agent output. answer is markdown prose with [n]\ncitation markers. cards reuse the sibling TakoCard. citations is the\nunified top-level registry for data and web sources — there is no\nweb_results field. metadata carries definitions, assumptions, and\nmethodology. The structured_output_* fields carry the caller-shaped\noutput_schema result; they are present only if the request supplied\noutput_schema. See each field's description for the exact presence\nrules.");
export type RetrievalAgentResult = z.infer<typeof RetrievalAgentResult>;

export const RetrievalAgentResultEvent = z.object({ "kind": z.literal("agent_result").default("agent_result"), "id": z.string(), "data": z.lazy(() => RetrievalAgentResult) });
export type RetrievalAgentResultEvent = z.infer<typeof RetrievalAgentResultEvent>;

export const RetrievalAgentRun = z.object({ "run_id": z.string(), "object": z.literal("agent.retrieval.run").default("agent.retrieval.run"), "thread_id": z.union([z.string(), z.null()]).optional(), "status": z.lazy(() => AgentRunStatus), "created_at": z.string(), "completed_at": z.union([z.string(), z.null()]).optional(), "result": z.union([z.lazy(() => RetrievalAgentResult), z.null()]).optional(), "error": z.union([z.lazy(() => ErrorObject), z.null()]).optional(), "usage": z.union([z.lazy(() => Usage), z.null()]).optional(), "request": z.union([z.lazy(() => RetrievalAgentRunRequest), z.null()]).optional() }).describe("The retrieval-agent run resource returned by dispatch (202) and poll (GET).");
