export const RetrievalAgentRunList = z.object({ "object": z.literal("list").default("list"), "data": z.array(z.lazy(() => RetrievalAgentRunSummary)), "has_more": z.boolean().default(false), "next_cursor": z.union([z.string(), z.null()]).optional() }).describe("List envelope for GET /v1/agent/retrieval/runs. The shape follows the\nOpenAI and Exa list convention.");
export type RetrievalAgentRunList = z.infer<typeof RetrievalAgentRunList>;

export const RetrievalAgentRunRequest = z.object({ "query": z.string().describe("Natural-language data-retrieval request for the retrieval agent."), "thread_id": z.union([z.string().uuid(), z.null()]).describe("Existing thread to continue (follow-up). Omit to start a new thread.").optional(), "effort": z.lazy(() => RetrievalAgentEffort).describe("Retrieval-agent effort. Only 'medium' is currently supported.").default("medium"), "source_indexes": z.array(z.enum(["data","web"])).describe("Which sources the agent may use: 'data' (curated knowledge), 'web' (open-web search), or both. Defaults to ['data', 'web']. Tako accepts the legacy value 'tako' as a synonym for 'data'.").optional(), "cards": z.boolean().describe("Whether the agent may build visualization cards. The default is true and permissive: the agent may build cards, but it does not have to (a completed run with no cards is legitimate). Set false to suppress card building entirely.").default(true), "output_schema": z.union([z.record(z.string(), z.any()), z.null()]).describe("JSON Schema for structured output. The agent writes the synthesized fields. Dataset slots (marked with x-tako-dataset: true) receive exact retrieved rows as a TakoDataset. Supported subset: the object, array, string, number, integer, and boolean types, plus enum, required, and description. Caps: 16KB, depth 5, 64 properties, 4 dataset slots. Violations return 400 output_schema_invalid.").optional(), "locale": z.string().describe("BCP-47 locale. Drives the language of the agent's answer and the locale used when rendering card preview images. Defaults to en-US.").default("en-US"), "timezone": z.union([z.string(), z.null()]).describe("IANA timezone (for example, 'America/New_York'). The agent uses it to render dates and times in card preview images. It does not affect the returned data.").optional(), "output_settings": z.union([z.lazy(() => AgentOutputSettings), z.null()]).describe("Settings that control the response and rendering.").optional() }).describe("Request body for POST /v1/agent/retrieval/runs.");
export type RetrievalAgentRunRequest = z.infer<typeof RetrievalAgentRunRequest>;

export const RetrievalAgentRunSummary = z.object({ "run_id": z.string(), "status": z.lazy(() => AgentRunStatus), "created_at": z.string(), "completed_at": z.union([z.string(), z.null()]).optional(), "thread_id": z.union([z.string(), z.null()]).optional(), "usage": z.union([z.lazy(() => Usage), z.null()]).optional(), "object": z.literal("agent.retrieval.run").default("agent.retrieval.run") });
export type RetrievalAgentRunSummary = z.infer<typeof RetrievalAgentRunSummary>;

export const RetrievalAgentStreamEnvelope = z.object({ "seq": z.number().int().gte(0), "run_id": z.string(), "thread_id": z.union([z.string(), z.null()]).optional(), "category": z.lazy(() => StreamCategory), "block": z.any().superRefine((x, ctx) => {
    const schemas = [z.lazy(() => ToolCallEvent), z.lazy(() => ToolResultEvent), z.lazy(() => ToolErrorEvent), z.lazy(() => ToolRetryEvent), z.lazy(() => StatusEvent), z.lazy(() => SubagentEvent), z.lazy(() => ReasoningEvent), z.lazy(() => TextEvent), z.lazy(() => DataPipelineAnswerEvent), z.lazy(() => RetrievalAgentResultEvent), z.lazy(() => RunSummaryEvent), z.lazy(() => HeartbeatEvent), z.lazy(() => StreamResetEvent), z.lazy(() => StreamDoneEvent)];
    const { errors, failed } = schemas.reduce<{
      errors: z.core.$ZodIssue[];
      failed: number;
    }>(
      ({ errors, failed }, schema) =>
        ((result) =>
          result.error
            ? {
                errors: [...errors, ...result.error.issues],
                failed: failed + 1,
              }
            : { errors, failed })(
          schema.safeParse(x),
        ),
      { errors: [], failed: 0 },
    );
    const passed = schemas.length - failed;
    if (passed !== 1) {
      ctx.addIssue(errors.length ? {
        path: [],
        code: "invalid_union",
        errors: [errors],
        message: "Invalid input: Should pass single schema. Passed " + passed,
      } : {
        path: [],
        code: "custom",
        errors: [errors],
        message: "Invalid input: Should pass single schema. Passed " + passed,
      });
    }
  }) }).describe("Public SSE envelope for the Retrieval Agent run stream. It has the same\nwire shape as AgentStreamEnvelope. The only difference is that the\nterminal agent_result block carries RetrievalAgentResult (unified\ntop-level citations, no web_results), so the SSE terminal matches the\nGET poll result.");
export type RetrievalAgentStreamEnvelope = z.infer<typeof RetrievalAgentStreamEnvelope>;

export const RunSummaryEvent = z.object({ "kind": z.literal("run_summary").default("run_summary"), "status": z.lazy(() => AgentRunStatus), "created_at": z.string(), "completed_at": z.union([z.string(), z.null()]).optional(), "error": z.union([z.lazy(() => ErrorObject), z.null()]).optional(), "usage": z.union([z.lazy(() => Usage), z.null()]).optional() }).describe("Terminal run metadata. The stream emits it once, immediately before\nstream_done. It mirrors the GET-poll run fields that the stream otherwise\nlacks; the result stays in the agent_result event. status, created_at,\nand completed_at are always present. error appears only on failure. usage\nappears only on metered (pay-as-you-go) runs and is null otherwise.\nagent_result plus run_summary equals the GET poll object.\n\nIt carries the same envelope `seq` as the stream_done that follows it (it\nhas no seq of its own), and the stream suppresses its SSE `id:`, so it\nadvances no resume cursor. Identify it by `kind`; never assume `seq` is\nunique per frame.");
export type RunSummaryEvent = z.infer<typeof RunSummaryEvent>;

export const SearchEffortLevel = z.enum(["fast","instant","deep"]).describe("Public effort taxonomy for search and answer. FAST is the default.\nINSTANT serves cached embeds without a new data retrieval and works in\nall environments. DEEP widens Tako retrieval and adds an LLM rerank for\nhigher-quality results; it is slower and bills at a premium tier.");
export type SearchEffortLevel = z.infer<typeof SearchEffortLevel>;

export const SearchRequest = z.object({ "query": z.string().describe("Natural language search query."), "effort": z.lazy(() => SearchEffortLevel).describe("Search effort level: 'fast' (default), 'instant', or 'deep'.").default("fast"), "sources": z.lazy(() => Sources).describe("Per-source settings. The search includes an index only if its key is present. Defaults to {data:{}, web:{}} (data and web, count 5 each). Tako accepts the legacy key 'tako' as a synonym for 'data'.").optional(), "location": z.union([z.lazy(() => GeoLocation), z.null()]).describe("Optional coordinates of the end user. Resolves the location for implicit-location queries (for example, weather). An explicit location in the query overrides these coordinates.").optional(), "country_code": z.string().describe("ISO 3166-1 alpha-2 country code for localization.").default("US"), "locale": z.string().describe("BCP-47 locale tag for language and formatting.").default("en-US"), "timezone": z.union([z.string(), z.null()]).describe("IANA timezone (for example, 'America/New_York').").optional(), "output_settings": z.union([z.lazy(() => OutputSettings), z.null()]).describe("Settings that control the response shape.").optional(), "include_related": z.union([z.number().int().gte(1).lte(20), z.null()]).describe("Applies to POST /v3/search only. Return follow-up query suggestions in `related`. Omit this field to disable them. The value sets the maximum number of suggestions, from 1 to 20. POST /v1/answer accepts this field but ignores it: the answer response has no `related` field.").optional() }).strict().describe("Shared request for POST /api/v3/search and POST /api/v1/answer.");
export type SearchRequest = z.infer<typeof SearchRequest>;

export const SearchResponse = z.object({ "cards": z.array(z.lazy(() => TakoCard)).optional(), "web_results": z.array(z.lazy(() => WebResult)).optional(), "request_id": z.string(), "usage": z.union([z.lazy(() => Usage), z.null()]).optional(), "related": z.union([z.array(z.lazy(() => RelatedSuggestion)), z.null()]).describe("Follow-up queries you can run next. Set `include_related` on the request to receive them. Absent when you did not ask for them, or when Tako found none.").optional() });
export type SearchResponse = z.infer<typeof SearchResponse>;

export const Sources = z.object({ "data": z.union([z.lazy(() => DataSourceSettings), z.null()]).describe("Tako data source (curated knowledge). The search includes it only if present. Tako accepts the legacy key 'tako' as a synonym.").optional(), "web": z.union([z.lazy(() => WebSourceSettings), z.null()]).describe("Web source. The search includes it only if present.").optional() }).strict().describe("Per-source settings. The search includes an index only if its field is\npresent.\n\nThe Tako data source is named `data`. Tako still accepts the legacy key\n`tako` as a synonym and maps it to `data` before validation.");
export type Sources = z.infer<typeof Sources>;

export const StatusEvent = z.object({ "kind": z.literal("status").default("status"), "message": z.string(), "parent_id": z.union([z.string(), z.null()]).optional() });
export type StatusEvent = z.infer<typeof StatusEvent>;

export const StreamCategory = z.enum(["content","activity","control"]);
export type StreamCategory = z.infer<typeof StreamCategory>;

export const StreamDoneEvent = z.object({ "kind": z.literal("stream_done").default("stream_done") });
export type StreamDoneEvent = z.infer<typeof StreamDoneEvent>;

export const StreamResetEvent = z.object({ "kind": z.literal("stream_reset").default("stream_reset") });
export type StreamResetEvent = z.infer<typeof StreamResetEvent>;

export const StructuredOutputStatus = z.enum(["complete","partial","failed"]).describe("Terminal status of the structured-output channel.");
export type StructuredOutputStatus = z.infer<typeof StructuredOutputStatus>;

export const SubagentEvent = z.object({ "kind": z.literal("subagent").default("subagent"), "agent_id": z.string(), "subagent_type": z.string(), "parent_id": z.union([z.string(), z.null()]).optional(), "event": z.enum(["dispatch","complete"]) });
export type SubagentEvent = z.infer<typeof SubagentEvent>;

export const TakoCard = z.object({ "card_id": z.union([z.string(), z.null()]).optional(), "title": z.union([z.string(), z.null()]).optional(), "description": z.union([z.string(), z.null()]).optional(), "semantic_description": z.union([z.string(), z.null()]).optional(), "webpage_url": z.union([z.string(), z.null()]).optional(), "image_url": z.union([z.string(), z.null()]).optional(), "embed_url": z.union([z.string(), z.null()]).optional(), "sources": z.union([z.array(z.lazy(() => TakoCardSource)), z.null()]).optional(), "methodologies": z.union([z.array(z.lazy(() => KnowledgeCardMethodology)), z.null()]).optional(), "source_indexes": z.union([z.array(z.lazy(() => TakoSourceIndex)), z.null()]).optional(), "card_type": z.union([z.string(), z.null()]).optional(), "relevance": z.union([z.lazy(() => KnowledgeCardRelevance), z.null()]).optional(), "content": z.union([z.lazy(() => ResultContent), z.null()]).optional(), "exportable": z.boolean().describe("Whether the /contents endpoint can download this card's data. false means the export is not available; use the card's chart and inline preview instead. true means the export is eligible but not guaranteed; the /contents endpoint can still return 403, so fall back to the preview on error.").default(false), "relevance_score": z.union([z.number(), z.null()]).describe("Numeric relevance of this card to the query on a 1.0-5.0 scale (5.0 = exact match; higher is more relevant). Only populated for entitled accounts; null otherwise.").optional(), "nodes": z.union([z.array(z.lazy(() => TakoCardNode)), z.null()]).describe("Graph nodes (entities and metrics) behind this card. The response includes them by default. Absent for web-only cards or when node resolution was not available. Use each id with /v1/graph/node/{id} for full detail (aliases, subtype), or pass ids in sources.data.node_ids to pin these nodes in future searches.").optional(), "metric_definitions": z.union([z.array(z.lazy(() => MetricDefinition)), z.null()]).describe("Definitions of the metrics this card displays (name + definition). Null when no displayed metric has a definition available.").optional(), "data_freshness": z.union([z.lazy(() => DataFreshness), z.null()]).describe("Freshness dates for the card's data: where the data ends (coverage_end), the same point as a full date (data_as_of, deprecated), and the last refresh date (last_updated). Null when no date is available.").optional() }).describe("A Tako knowledge card on the search and answer surfaces. It carries a\n`content` download descriptor.");
export type TakoCard = z.infer<typeof TakoCard>;

export const TakoCardNode = z.object({ "id": z.string().describe("Opaque, human-friendly public id (<prefix>::<name>::<hash>, where prefix is ent for an entity or mt for a metric). Ids are not durable across knowledge-graph rebuilds — resolve them at request time rather than storing them."), "type": z.lazy(() => GraphNodeType), "name": z.string(), "description": z.union([z.string(), z.null()]).optional() }).describe("Slim graph node for the search and answer card surface\n(TakoCard.nodes). It is deliberately narrower than GraphNode: it carries\nno `aliases` and no `subtype`. Callers that need the full node resolve\nthe id via /v1/graph/node/{id}.");
export type TakoCardNode = z.infer<typeof TakoCardNode>;

export const TakoCardSource = z.object({ "source_name": z.union([z.string(), z.null()]).describe("The name of the source").optional(), "source_description": z.union([z.string(), z.null()]).describe("The description of the source").optional(), "source_index": z.lazy(() => TakoSourceIndex).describe("The index of the source"), "url": z.union([z.string(), z.null()]).describe("The URL of the source").optional(), "source_text": z.union([z.string(), z.null()]).describe("Raw excerpts retrieved from the source page — the unmodified web content that grounded the answer. Present for WEB sources; null for DATA sources.").optional() }).describe("A source that backs a TakoCard on the SDK surfaces. It uses the\n{data, web} TakoSourceIndex taxonomy.");
export type TakoCardSource = z.infer<typeof TakoCardSource>;

export const TakoDatasetColumn = z.object({ "name": z.string().describe("Column name."), "type": z.lazy(() => TakoDatasetColumnType).describe("Logical column type: 'string', 'number', 'boolean', 'date', or 'datetime'. Temporal cells are ISO-8601 strings."), "unit": z.union([z.string(), z.null()]).describe("Structured unit for the column values, e.g. 'USD billions', '%'. Null when unitless.").optional() }).describe("Typed header entry; `type` is the JSON-facing column type.");
export type TakoDatasetColumn = z.infer<typeof TakoDatasetColumn>;

export const TakoDatasetColumnType = z.enum(["string","number","boolean","date","datetime"]).describe("Logical column type declared in a TakoDataset header. Temporal cells\nare ISO-8601 strings. Each column declares 'date' or 'datetime' on its\nown: a temporal column whose non-null values are all timezone-naive\nmidnights declares 'date'.");
export type TakoDatasetColumnType = z.infer<typeof TakoDatasetColumnType>;

export const TakoDatasetSource = z.object({ "name": z.string().describe("Human-readable source name (e.g. 'FRED', 'S&P Global')."), "index": z.enum(["data","web"]).describe("Source index the rows came from: 'data' (Tako) or 'web'.").default("data") }).describe("Per-dataset provenance entry. `index` names the source index, not a\ncitation display number. It is \"data\" for every dataset today — web\ncontent never fills a dataset slot.");
export type TakoDatasetSource = z.infer<typeof TakoDatasetSource>;

export const TakoSourceIndex = z.enum(["data","web"]).describe("Public source taxonomy for the SDK card surfaces (v3 search, v1 answer,\nagent). It is symmetric with the request taxonomy {data, web}.");
export type TakoSourceIndex = z.infer<typeof TakoSourceIndex>;

export const TextEvent = z.object({ "kind": z.literal("text").default("text"), "id": z.string(), "delta": z.string(), "done": z.boolean().default(false) });
export type TextEvent = z.infer<typeof TextEvent>;

export const ThinVizCard = z.object({ "card_id": z.union([z.string(), z.null()]).describe("Public ID of the created card.").optional(), "title": z.union([z.string(), z.null()]).describe("Card title.").optional(), "description": z.union([z.string(), z.null()]).describe("Card description.").optional(), "webpage_url": z.union([z.string(), z.null()]).describe("Hosted page URL for the card.").optional(), "image_url": z.union([z.string(), z.null()]).describe("Static preview image URL for the card.").optional(), "embed_url": z.union([z.string(), z.null()]).describe("Embeddable URL for the card.").optional(), "card_type": z.union([z.string(), z.null()]).describe("The card's chart type (for example, 'bar').").optional(), "visualization_data": z.union([z.record(z.string(), z.any()), z.null()]).describe("Inline chart config + data for rendering the card.").optional(), "embed_mode": z.union([z.enum(["post","postmessage"]), z.null()]).describe("How Tako delivers the embed: 'postmessage' for postMessage embeds, and 'post' otherwise.").optional() }).describe("Response for POST /api/v1/thin_viz/create — a created visualization card.\n\nDistinct from KnowledgeCard: thin_viz builds a self-contained chart from\na caller-supplied component schema, so it never carries retrieval\nprovenance (sources, source_indexes) or downloadable raw data. Render the\ncard via `embed_url` and preview it via `image_url`.\n`visualization_data` carries the inline chart config and data.\n\nThis schema documents the populated subset of the response. The wire\npayload also includes the remaining KnowledgeCard fields (sources,\nsource_indexes, methodologies, data_url, and so on) as null.");
export type ThinVizCard = z.infer<typeof ThinVizCard>;

export const ToolCallEvent = z.object({ "kind": z.literal("tool_call").default("tool_call"), "id": z.string(), "tool": z.string(), "status_message": z.union([z.string(), z.null()]).optional(), "parent_id": z.union([z.string(), z.null()]).optional(), "done": z.boolean().default(false) });
export type ToolCallEvent = z.infer<typeof ToolCallEvent>;

export const ToolErrorEvent = z.object({ "kind": z.literal("tool_error").default("tool_error"), "id": z.string(), "tool": z.string(), "error": z.string(), "parent_id": z.union([z.string(), z.null()]).optional() });
export type ToolErrorEvent = z.infer<typeof ToolErrorEvent>;

export const ToolResultEvent = z.object({ "kind": z.literal("tool_result").default("tool_result"), "id": z.string(), "tool": z.string(), "elapsed_ms": z.number().int().default(0), "link": z.union([z.string(), z.null()]).optional(), "parent_id": z.union([z.string(), z.null()]).optional() });
export type ToolResultEvent = z.infer<typeof ToolResultEvent>;

export const ToolRetryEvent = z.object({ "kind": z.literal("tool_retry").default("tool_retry"), "id": z.string(), "tool": z.string(), "error": z.string(), "elapsed_ms": z.number().int().default(0), "parent_id": z.union([z.string(), z.null()]).optional() });
export type ToolRetryEvent = z.infer<typeof ToolRetryEvent>;

export const Usage = z.object({ "total_cost_usd": z.number().describe("Total quoted USD cost of this request. Sum of compute cost and data cost."), "compute": z.union([z.lazy(() => UsageCompute), z.null()]).describe("Compute cost breakdown. Present only on surfaces with a compute step (absent for contents).").optional(), "data": z.union([z.lazy(() => UsageData), z.null()]).describe("Inline-data cost breakdown. Present only when the surface emitted billable inline data.").optional() }).describe("Usage for one metered request. `total_cost_usd` is always present (the\ntotal quoted charge). `compute` and `data` are the additive breakdown;\neach appears only where it applies. total_cost_usd always equals the sum\nof the components that appear.");
export type Usage = z.infer<typeof Usage>;

export const UsageCompute = z.object({ "cost_usd": z.number().describe("USD cost of running the operation.") }).describe("The cost of running the operation. Absent on surfaces with no compute\nstep (contents).");
export type UsageCompute = z.infer<typeof UsageCompute>;

export const UsageData = z.object({ "cost_usd": z.number().describe("USD cost of the inline data delivered in the response."), "datasets": z.number().int().describe("Number of billed data units (datasets) included in the response.") }).describe("The cost and quantity of inline data delivered in the response: the\nagent per-dataset surcharge, the search and answer include_contents\ncharge, or the contents per-item cost. `datasets` is the count of billed\ndata units. Absent when the surface did not or cannot emit inline data\n(for example, the answer agent).");
export type UsageData = z.infer<typeof UsageData>;

export const WebCategory = z.enum(["news","sports","finance"]).describe("Web search category filter. Only 'news' maps to a provider category\ntoday; 'sports' and 'finance' are accepted but have no effect yet.");
export type WebCategory = z.infer<typeof WebCategory>;

export const WebResult = z.object({ "title": z.string().describe("Title of the web page."), "url": z.string().describe("URL of the web page."), "snippet": z.union([z.string(), z.null()]).describe("Excerpt(s) from the page that matched the query.").optional(), "source_name": z.union([z.string(), z.null()]).describe("Publisher or domain name, when Tako can extract it from the URL.").optional(), "publish_date": z.union([z.string(), z.null()]).describe("Publication date of the page, when available.").optional(), "content": z.union([z.lazy(() => ResultContent), z.null()]).describe("Downloadable content descriptor for this result, fetched via the Contents endpoint. Web results are always downloadable as text. None for callers that do not populate it.").optional(), "citation_number": z.union([z.number().int(), z.null()]).describe("1-based citation number that the answer's inline [N] markers reference. Set only when the answer inline-cites this result (the Agent API); None on raw-retrieval surfaces.").optional() }).describe("A single raw web search result from the WEB source index.\n\nDistinct from `KnowledgeCardSource` (a citation inside a synthesized\nanswer) and `KnowledgeCard` (a Tako visualization). Web results are\nraw retrieval output — title, URL, optional snippet. They do not depend\non any LLM synthesis that may also happen over them.");
export type WebResult = z.infer<typeof WebResult>;

export const WebSourceSettings = z.object({ "count": z.union([z.number().int().gte(1).lte(20), z.null()]).describe("Maximum number of results to return for this source. The range is 1 to 20. If you omit this field, the search endpoint returns 5 results and the answer endpoint returns 3.").optional(), "include_contents": z.boolean().describe("Inline this source's underlying data directly in the response. For the Tako data source, that is serialized card data (see content_format). For web results, that is the extracted text.").default(false), "category": z.union([z.lazy(() => WebCategory), z.null()]).describe("Restrict web results to a category. 'news' filters to news sources. 'sports' and 'finance' are accepted but have no effect yet. Omit for a general web search.").optional(), "include_domains": z.array(z.string()).max(20).describe("Return only results from these domains (bare hosts, for example 'cnn.com'). Max 20.").optional(), "exclude_domains": z.array(z.string()).max(20).describe("Drop results from these domains (bare hosts, for example 'cnn.com'). Max 20.").optional(), "snippet_max_chars": z.union([z.number().int().gte(1).lte(20000), z.null()]).describe("Character cap on the text excerpt returned per web result. If you omit this field, the search endpoint applies 4000 and the answer endpoint applies 1000. If you send a value, the server uses that value exactly. The maximum is 20000.").optional(), "highlights": z.boolean().describe("Return query-relevant highlight passages as each web result's snippet, instead of the opening text of the page. Highlights usually carry the answer-bearing sentences, and stay within snippet_max_chars. Tako requests no page text when this field is true, so a page with no highlight returns snippet: null. The snippet can also hold more than one passage from different parts of the page, joined by ' … '. Read the snippet as a whole. Do not cut the snippet to a fixed length. Do not quote the snippet as one continuous sentence. Default false.").default(false), "article_content_max_chars": z.number().int().gte(1).lte(1000000).describe("Character cap on the full article text when include_contents is true. Default 30000, maximum 1000000.").default(30000), "published_after": z.union([z.string().date(), z.null()]).describe("Keep only web results published on or after this date (ISO 'YYYY-MM-DD'). Tako applies the date on the provider where possible, and always filters the returned results. Results with no known publication date are kept. Omit for no lower bound.").optional(), "published_before": z.union([z.string().date(), z.null()]).describe("Keep only web results published on or before this date (ISO 'YYYY-MM-DD'). Results with no known publication date are kept. Omit for no upper bound.").optional() }).strict().describe("Web source settings. Adds category, domain filters, and character caps\non top of the base count and include_contents.");
export type WebSourceSettings = z.infer<typeof WebSourceSettings>;
